package com.heng.community;
import com.heng.controller.ApiResponse;
import com.heng.config.BizException;
import org.springframework.web.bind.annotation.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

@RestController @RequestMapping("/api")
public class StoreCouponController {
 private final JdbcTemplate db;public StoreCouponController(JdbcTemplate db){this.db=db;}
 @GetMapping("/stores") public ApiResponse<?> stores(){return ApiResponse.ok(db.queryForList("SELECT store_id AS \"storeId\",name,address,hours,phone,description FROM v_store WHERE status=1 ORDER BY store_id"));}
 @GetMapping("/member/store") public ApiResponse<?> selected(@RequestAttribute("viridac.memberId") long me){var rows=db.queryForList("SELECT s.store_id AS \"storeId\",s.name,s.address,s.hours,s.phone,s.description FROM v_member_store m JOIN v_store s ON s.store_id=m.store_id WHERE m.member_id=? AND s.status=1",me);return ApiResponse.ok(rows.isEmpty()?null:rows.get(0));}
 public record Selection(Long storeId){}
 @PutMapping("/member/store") @Transactional public ApiResponse<?> select(@RequestAttribute("viridac.memberId") long me,@RequestBody Selection q){db.queryForList("SELECT member_id FROM v_member WHERE member_id=? FOR UPDATE",me);if(q.storeId()==null){db.update("DELETE FROM v_member_store WHERE member_id=?",me);return ApiResponse.ok(null);}requireStore(q.storeId());db.update("DELETE FROM v_member_store WHERE member_id=?",me);db.update("INSERT INTO v_member_store(member_id,store_id) VALUES(?,?)",me,q.storeId());return selected(me);}
 public Map<String,Object> requireStore(long id){var rows=db.queryForList("SELECT * FROM v_store WHERE store_id=? AND status=1",id);if(rows.isEmpty())throw new BizException("门店已停用，请重新选择");return rows.get(0);}
 public void attachOrder(long me,long order,Long storeId){if(storeId==null)return;var store=requireStore(storeId);db.update("INSERT INTO v_order_store(order_id,store_id,name_snapshot,address_snapshot) VALUES(?,?,?,?) ON CONFLICT DO NOTHING",order,storeId,store.get("name"),store.get("address"));}
 @GetMapping("/orders/{id}/store") public ApiResponse<?> orderStore(@RequestAttribute("viridac.memberId") long me,@PathVariable long id){if(db.queryForObject("SELECT COUNT(*) FROM v_order WHERE order_id=? AND member_id=?",Long.class,id,me)!=1)throw new BizException("订单不存在");var rows=db.queryForList("SELECT store_id AS \"storeId\",name_snapshot AS name,address_snapshot AS address FROM v_order_store WHERE order_id=?",id);return ApiResponse.ok(rows.isEmpty()?null:rows.get(0));}
 @GetMapping("/coupons/claimable") public ApiResponse<?> claimable(@RequestAttribute("viridac.memberId") long me){return ApiResponse.ok(db.queryForList("SELECT c.coupon_id AS \"couponId\",c.name,c.coupon_type AS \"couponType\",c.value_fen AS \"valueFen\",c.discount_bps AS \"discountBps\",c.min_amount_fen AS \"minAmountFen\",c.description,c.valid_to AS \"validTo\",c.per_member_limit AS \"perMemberLimit\",c.total_count AS \"totalCount\",c.remain_count AS \"remainCount\",(SELECT COUNT(*) FROM v_member_coupon m WHERE m.member_id=? AND m.coupon_id=c.coupon_id) AS \"receivedCount\" FROM v_coupon c JOIN v_coupon_publication p ON p.coupon_id=c.coupon_id AND p.enabled=1 WHERE c.status=1 AND c.valid_from<=NOW() AND c.valid_to>NOW() ORDER BY c.coupon_id DESC LIMIT 100",me));}
 @PostMapping("/coupons/{id}/claim") @Transactional public ApiResponse<?> claim(@RequestAttribute("viridac.memberId") long me,@PathVariable long id){db.queryForList("SELECT member_id FROM v_member WHERE member_id=? FOR UPDATE",me);var rows=db.queryForList("SELECT c.* FROM v_coupon c JOIN v_coupon_publication p ON p.coupon_id=c.coupon_id AND p.enabled=1 WHERE c.coupon_id=? AND c.status=1 AND c.valid_from<=NOW() AND c.valid_to>NOW() FOR UPDATE",id);if(rows.isEmpty())throw new BizException("优惠券未开放领取或已过期");var c=rows.get(0);long owned=db.queryForObject("SELECT COUNT(*) FROM v_member_coupon WHERE member_id=? AND coupon_id=?",Long.class,me,id),limit=((Number)c.get("per_member_limit")).longValue();if(limit>0&&owned>=limit)throw new BizException("已达个人领券上限");if(db.update("UPDATE v_coupon SET remain_count=CASE WHEN total_count=0 THEN remain_count ELSE remain_count-1 END WHERE coupon_id=? AND (total_count=0 OR remain_count>0)",id)!=1)throw new BizException("优惠券已领完");db.update("INSERT INTO v_member_coupon(member_id,coupon_id,status,received_time,expire_time) VALUES(?,?,'AVAILABLE',NOW(),?)",me,id,c.get("valid_to"));return ApiResponse.ok(null);}
}
